REVOKE ALL ON TABLE "public"."WorkerStatement" FROM PUBLIC, "factory_floor_runtime", "factory_partner_runtime", "factory_platform", "factory_runtime";
GRANT SELECT, INSERT, UPDATE ON TABLE "public"."WorkerStatement" TO "factory_runtime";
CREATE POLICY "factory_runtime_select" ON "public"."WorkerStatement" AS PERMISSIVE FOR SELECT TO "factory_runtime" USING ("tenantId" = NULLIF(current_setting('factory.tenant_id', true), '')::uuid);
CREATE POLICY "factory_runtime_insert" ON "public"."WorkerStatement" AS PERMISSIVE FOR INSERT TO "factory_runtime" WITH CHECK ("tenantId" = NULLIF(current_setting('factory.tenant_id', true), '')::uuid);
CREATE POLICY "factory_runtime_update" ON "public"."WorkerStatement" AS PERMISSIVE FOR UPDATE TO "factory_runtime" USING ("tenantId" = NULLIF(current_setting('factory.tenant_id', true), '')::uuid) WITH CHECK ("tenantId" = NULLIF(current_setting('factory.tenant_id', true), '')::uuid);
