-- 5. Platform tables
-- "public"."Tenant": factory_platform
GRANT SELECT, INSERT, UPDATE ON TABLE "public"."Tenant" TO "factory_platform";
CREATE POLICY "factory_platform_select" ON "public"."Tenant" AS PERMISSIVE FOR SELECT TO "factory_platform" USING (true);
CREATE POLICY "factory_platform_insert" ON "public"."Tenant" AS PERMISSIVE FOR INSERT TO "factory_platform" WITH CHECK (true);
CREATE POLICY "factory_platform_update" ON "public"."Tenant" AS PERMISSIVE FOR UPDATE TO "factory_platform" USING (true) WITH CHECK (true);
